using Mcacc.Core.Quoting;

namespace Mcacc.Core.Terminal;

public static class PosixCommandFileBuilder
{
    public static string Build(CliLaunchRequest req)
    {
        string[] lines =
        [
            "#!/bin/zsh",
            "# Generated by MCACC - overwritten on every launch.",
            req.ConfigDirOverride is null
                ? $"unset {req.ConfigDirVariable}"
                : $"export {req.ConfigDirVariable}={PosixQuoting.SingleQuote(req.ConfigDirOverride)}",
            $"unset {string.Join(' ', req.Scrub)}",
            @"cd ""$HOME"" || exit 1",
            @"printf '\033]0;%s\007' " + PosixQuoting.SingleQuote(req.Title),
            // A login shell, so the CLI is found on the PATH the user's profile sets up.
            $"\"${{SHELL:-/bin/zsh}}\" -l -i -c '{req.CliCommand}'",
            @"exec ""${SHELL:-/bin/zsh}"" -l -i",
        ];
        return string.Concat(lines.Select(line => line + "\n"));
    }
}
